func TestHeadVersionRecordMustBeIntact(t *testing.T) {
	versionFrame := encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))

	cases := map[string][]byte{
		"magic only": []byte(logMagic),
