244		got := resultFor(t, rep, "m90")
245		if got.Status != "success" {
246			t.Fatalf("proof-at-90 must deliver after conflict: %+v", got)
247		}
248		if want := "delivered; proof verified by trusted header at height 100"; got.Reason != want {
249			t.Fatalf("success reason must cite the actually-used trusted height 100: %q", got.Reason)
250		}
251	
252		submitMsg(t, state, "m101", "chain-a", "chain-b", 2, 101)
253		rep = advanceCLI(t, state, 1_700_000_100_000)
254		waiting := resultFor(t, rep, "m101")
255		if want := "waiting for trusted header covering height 101 (current 100)"; waiting.Status != "waiting" || waiting.Reason != want {
