263	// Saving a header never processes messages: after a conflicting (or
264	// idempotent) header save, an already waiting record must keep exactly its
265	// status, reason, attempt count and scheduled retry time.
266	func TestCLIConflictHeaderSaveLeavesWaitingRecordUntouched(t *testing.T) {
267		state := t.TempDir()
268		registerSource(t, state, "chain-a")
